//! The Re-Link brand: the status colours and the icon files. The files in
//! `assets/brand/` are generated by `scripts/brand` (one description renders
//! the .ico, the window PNG, the tray tiles and the banners); nothing is drawn
//! at run time.

use crate::diagnose::Status;

pub type Rgb = [u8; 3];

pub const GREEN: Rgb = [0x2E, 0x9E, 0x5B];
pub const AMBER: Rgb = [0xE0, 0x9B, 0x1A];
pub const RED: Rgb = [0xD1, 0x3A, 0x3A];
pub const GRAY: Rgb = [0x7A, 0x80, 0x88];
pub const BLUE: Rgb = [0x2F, 0x6F, 0xD6];

/// The window and notification icon (PNG, 256 px).
pub static ICON_PNG: &[u8] = include_bytes!("../assets/brand/icon-256.png");
/// The Windows icon (PNG frames from 16 to 256 px), also embedded in the exe.
pub static ICON_ICO: &[u8] = include_bytes!("../assets/brand/relink.ico");

/// Side of the tray tiles, in pixels.
pub const TRAY_SIZE: u32 = 32;

/// The tray tile for a status: straight RGBA, `TRAY_SIZE` squared, top-down.
pub fn tray_rgba(status: Option<Status>) -> &'static [u8] {
    match status {
        None => include_bytes!("../assets/brand/tray-idle.rgba"),
        Some(Status::Ok) => include_bytes!("../assets/brand/tray-ok.rgba"),
        Some(Status::VpnDown) => include_bytes!("../assets/brand/tray-vpn-down.rgba"),
        Some(Status::Settling) => include_bytes!("../assets/brand/tray-settling.rgba"),
        Some(Status::Stuck) => include_bytes!("../assets/brand/tray-stuck.rgba"),
        Some(Status::MissingRoute) => include_bytes!("../assets/brand/tray-missing.rgba"),
    }
}

/// The colour a status is shown in everywhere (pills, dots, the tray tile).
pub fn status_color(status: Option<Status>) -> Rgb {
    match status {
        None | Some(Status::Settling) => BLUE,
        Some(Status::Ok) => GREEN,
        Some(Status::VpnDown) => GRAY,
        Some(Status::Stuck) => AMBER,
        Some(Status::MissingRoute) => RED,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const ALL: [Option<Status>; 6] = [
        None,
        Some(Status::Ok),
        Some(Status::VpnDown),
        Some(Status::Settling),
        Some(Status::Stuck),
        Some(Status::MissingRoute),
    ];

    #[test]
    fn every_status_has_a_full_tray_tile() {
        for s in ALL {
            let px = tray_rgba(s);
            assert_eq!(px.len(), (TRAY_SIZE * TRAY_SIZE * 4) as usize, "{s:?}");
            // The tile is opaque in the middle and transparent in the corner.
            let at = |x: usize, y: usize| px[(y * TRAY_SIZE as usize + x) * 4 + 3];
            assert_eq!(at(16, 2), 255, "{s:?}: tile body");
            assert_eq!(at(0, 0), 0, "{s:?}: rounded corner");
        }
    }

    #[test]
    fn a_tray_tile_is_painted_in_its_status_colour() {
        for s in ALL {
            let px = tray_rgba(s);
            // A pixel on the tile's edge band, away from the white glyph.
            let i = (3 * TRAY_SIZE as usize + 16) * 4;
            assert_eq!(px[i..i + 3], status_color(s), "{s:?}");
        }
    }

    #[test]
    fn the_icons_are_real_image_files() {
        assert_eq!(&ICON_PNG[..8], b"\x89PNG\r\n\x1a\n");
        // ICONDIR: reserved 0, type 1 (icon), then the frame count.
        assert_eq!(&ICON_ICO[..4], [0, 0, 1, 0]);
        assert!(u16::from_le_bytes([ICON_ICO[4], ICON_ICO[5]]) >= 6);
    }
}
